import java.io.*;
import java.util.*;
public class CF_884F {
    public static final int MOD = 1000_000_000 + 7;
    public static final double EPS = 1e-6;
    public static final boolean DEBUG = true;

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        sc.nextLine(); // consume newline
        char[] s = sc.nextLine().trim().toCharArray();
        String[] tokens = sc.nextLine().trim().split("\\s");
        int[] beauty = new int[n];
        int ans = 0;
        int m = 0, x = 0, t = 0;
        int[] b = new int[101];
        int[] count = new int[26];

        for (int i = 0; i < n; i++) {
            beauty[i] = Integer.parseInt(tokens[i]);
            ans += beauty[i];
        }

        for (int i = 0; i < n / 2; i++) {
            if (s[i] == s[n - i - 1]) {
                t++;
                count[(int)(s[i] - 'a')]++;
                ans -= Math.min(beauty[i], beauty[n - i - 1]);
            }
        }

        for (int i = 0; i < 26; i++) {
            if (m < count[i]) {
                m = count[i];
                x = i;
            }
        }

        if (2 * m <= t) {
            System.out.println(ans);
            return;
        }
        ArrayList<Integer> list = new ArrayList<Integer>();

        for (int i = 0; i < n / 2; i++) {
            if ((int)(s[i] - 'a') != x && (int)(s[n - i - 1] - 'a') != x && s[i] != s[n - i - 1]) {
                list.add(Math.min(beauty[i], beauty[n - i - 1]));
            }
        }

        Collections.sort(list);
        for (int i = 0; i < 2 * m - t; i++) {
            ans -= list.get(i);
        }
        System.out.print(ans);
        sc.close();
    }
}
